import mongoose from 'mongoose';

const { ObjectId } = mongoose.Schema.Types;

export const CONTEXT_TYPES = ['ANNONCE', 'TRAJET', 'EVENEMENT'];

const messageSchema = new mongoose.Schema(
  {
    expediteur: { type: ObjectId, ref: 'Utilisateur', required: true },
    destinataire: { type: ObjectId, ref: 'Utilisateur', required: true },
    cleConversation: { type: String, required: true },
    contenu: { type: String, required: true, trim: true, maxlength: 2000 },
    // Generated by the sender's client; makes resends after a reconnect idempotent.
    clientId: { type: String, required: true, maxlength: 64 },
    contexte: {
      type: new mongoose.Schema({ type: { type: String, enum: CONTEXT_TYPES }, ref: ObjectId, libelle: String }, { _id: false }),
      default: null,
    },
    lu: { type: Boolean, default: false },
  },
  { timestamps: { createdAt: 'dateEnvoi', updatedAt: false } },
);

messageSchema.index({ cleConversation: 1, dateEnvoi: -1 });
messageSchema.index({ expediteur: 1, clientId: 1 }, { unique: true });
messageSchema.index({ destinataire: 1, lu: 1 });

export const Message = mongoose.model('Message', messageSchema, 'messages');

export const conversationKey = (a, b) => [String(a), String(b)].sort().join('_');
